<?php
namespace App\Policies;
use App\Models\{CrmPipeline,User}; use App\Policies\Concerns\CompanyOwnedPolicy; use Illuminate\Auth\Access\HandlesAuthorization;
class CrmPipelinePolicy { use HandlesAuthorization,CompanyOwnedPolicy; public function viewAny(User $u):bool{return $u->can('view_any_crm::pipeline');} public function view(User $u,CrmPipeline $r):bool{return $this->canForRecord($u,'view_crm::pipeline',$r);} public function create(User $u):bool{return $u->can('create_crm::pipeline');} public function update(User $u,CrmPipeline $r):bool{return $this->canForRecord($u,'update_crm::pipeline',$r);} public function delete(User $u,CrmPipeline $r):bool{return $this->canForRecord($u,'delete_crm::pipeline',$r)&&!$r->opportunities()->exists();} public function deleteAny(User $u):bool{return $u->can('delete_any_crm::pipeline');} public function restore(User $u,CrmPipeline $r):bool{return false;} public function restoreAny(User $u):bool{return false;} public function forceDelete(User $u,CrmPipeline $r):bool{return false;} public function forceDeleteAny(User $u):bool{return false;} public function replicate(User $u,CrmPipeline $r):bool{return false;} public function reorder(User $u):bool{return false;} }